"""Task guidance with native capability selection and registration preserved."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "discovery-question-classification"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = f"skills/{SKILL_NAME}/SKILL.md"
OPEN_SKILL_NAME = "discovery-open-followups"
OPEN_SKILL_ASSET = f"skills/{OPEN_SKILL_NAME}/SKILL.md"

GUIDANCE = """在准备首次需求沟通追问清单时：
1. 先确认本次适用的工作规则和客户线索。输入中已完整给出的内容直接使用；指定在工作目录或附件中的材料，用现有读取能力读全，遇截断续读缺少的部分。已完整读到且未变更的材料不要重复读取。
2. 本次清单的范围、结构、数量、问法及限制，以当次规则原文为准；按本次线索组织销售可直接照问的问题。不要把上一家公司或上一次沟通的口径、客户事实当作本次依据，也不要自行加上通用销售模板要求。
3. 拟题和标类别时，{case_guidance}先判断每题希望客户补充什么未知信息，再按本次定义标类别，不按痛点主题贴标签。混合内容无法由标签合理表达时，先收窄至所需的未知信息，必要时分别表达。当次要求开放式问法时，{open_guidance}在拟题及交付前，逐个核对题内每个追问（含后半句）与当次封闭问法定义，把是非判断改成对所需未知信息的具体询问，保留当次允许的相关合问。修改问法或类别后，按实际内容核对本次类别数量、必问与总题数；相关事项能否合问以当次规则为准。普通拟题问题在清单内修正并保留其余有效题，不改成澄清请求。交付前对照当次规则和线索：所写事实须有本次材料依据，问题与格式须符合当次要求。只输出规则要求的内容，不展示案例、内部判断、计数、阅读过程或额外说明。
4. 普通缺项先按当次规则规定的方式处理，保留有依据、符合要求的清单内容，不用计划或进度说明代替清单。若必要规则缺失、无法读取，或适用口径冲突且现有材料无法消解，只就阻碍交付的最小缺口请求澄清；不得猜测或用旧口径补齐。"""


class DiscoveryCapability(CapabilityStrategy):
    """Supply a stable method, not company rules or a semantic enforcement gate."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[SKILL_ASSET]},
                source="curator:R1:classification-examples",
            ),
            SkillContribution(
                name=OPEN_SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[OPEN_SKILL_ASSET]},
                source="curator:R2:open-followup-examples",
            ),
        )

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        counts: dict[tuple[str, str], int] = {}
        for skill in request.skills:
            identity = (skill.source, skill.name)
            counts[identity] = counts.get(identity, 0) + 1
        available = {
            (skill.source, skill.name)
            for skill in request.skills
            if skill.available and counts[(skill.source, skill.name)] == 1
        }
        bodies = available & {
            (SKILL_SOURCE, SKILL_NAME),
            (SKILL_SOURCE, OPEN_SKILL_NAME),
        }
        case_notes: dict[str, str] = {}
        for name, label, field in (
            (SKILL_NAME, "分类", "case_guidance"),
            (OPEN_SKILL_NAME, "开放追问", "open_guidance"),
        ):
            case_notes[field] = (
                f"先对照本次已附的{label}案例；"
                if (SKILL_SOURCE, name) in bodies
                else (
                    f"本次未取得可用的{label}案例，不要假称已对照；"
                    "直接依据当次规则继续。此供给说明不属于用户交付。"
                )
            )

        selected: list[SkillSelection] = []
        if bodies:
            for skill in request.skills:
                identity = (skill.source, skill.name)
                if identity not in available:
                    continue
                selected.append(SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if identity in bodies else "catalog",
                ))
        return CapabilitySelection(
            tools=None,
            skills=tuple(selected) if bodies else None,
            guidance=GUIDANCE.format(**case_notes),
        )


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> DiscoveryCapability:
    """Bind the registrar without reading or changing task or checkpoint data."""
    return DiscoveryCapability(registrar)
